const input = $input.first().json;

// Localiza o conteúdo CSV nas propriedades mais comuns
const csvRaw =
  input.body ??
  input.csv ??
  input.data ??
  input.text ??
  input.texto ??
  input.content;

let investimentos;

// Se já vier como lista de investimentos
if (Array.isArray(input.investimentos)) {
  investimentos = input.investimentos.map(obj => ({
    ...obj,
    minimo: Number(obj.minimo)
  }));
} else {
  // Se vier como texto CSV
  const text = typeof csvRaw === "string"
    ? csvRaw
    : null;

  if (!text || !text.trim()) {
    throw new Error(
      "CSV não encontrado. Verifique o JSON de entrada e identifique a propriedade que contém o texto."
    );
  }

  const lines = text
    .split(/\r?\n/)
    .map(l => l.trim())
    .filter(Boolean);

  const headers = lines[0].split(",").map(h => h.trim());

  investimentos = lines.slice(1).map(line => {
    const cols = line.split(",").map(c => c.trim());
    const obj = {};

    headers.forEach((h, i) => {
      obj[h] = cols[i] ?? "";
    });

    obj.minimo = Number(obj.minimo);

    return obj;
  });
}

return [{ json: { investimentos } }];

// Investimentos: vêm do Code 1
const investimentos = $input.first().json.investimentos;

// Clientes: vêm do nó Webhook
const webhook = $('Webhook').first().json;
const clientes = webhook.body?.clientes ?? webhook.clientes;

if (!Array.isArray(clientes)) {
  throw new Error("Lista de clientes não encontrada no nó Webhook (body.clientes).");
}

// "R$ 12.500,00" -> 12500
const parseSaldo = (texto) =>
  parseFloat(String(texto).replace('R$', '').trim().replace(/\./g, '').replace(',', '.'));

const formatarBRL = (valor) =>
  valor.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });

return clientes.map((cliente) => {
  const saldo = parseSaldo(cliente.saldo);

  const produtos = investimentos.filter(
    (i) => i.perfil === cliente.perfil && i.minimo <= saldo
  );

  const detalhes = produtos.length
    ? produtos
        .map((p) => `${p.produto} (rentabilidade: ${p.rentabilidade}; aplicação mínima: ${formatarBRL(p.minimo)})`)
        .join(' | ')
    : 'nenhum produto disponível para o saldo atual';

  return {
    json: {
      nome: cliente.nome,
      email: cliente.email,
      perfil: cliente.perfil,
      saldo,
      produtos: produtos.map((p) => p.produto),
      detalhes,
    },
  };
});

