return $input.all().map((item) => {
  const bruto = item.json.content?.find((c) => c.type === 'text')?.text
    ?? item.json.text
    ?? item.json.output;

  const limpo = (bruto ?? '').replace(/```json|```/g, '').trim();

  try {
    const { email, assunto, corpo } = JSON.parse(limpo);
    return { json: { email, assunto, corpo, ok: true } };
  } catch (e) {
    return { json: { ok: false, erro: 'JSON incompleto', bruto: limpo } };
  }
});
